    public static void testEveryCellIsPrintedOrNamedSpare() {
        // per arena of the field table: the cells its rows cover, plus its spare cells, are its stride, and no two rows overlap
        int a = 0;
        int k = 0;
        int covered = 0;
        int next = 0;
        int f = 0;
        while (a < 4) {
            covered = 0;
            next = 0;
            k = 0;
            while (k < Glayer.GL_FX[a * 4 + 1]) {
                f = Glayer.GL_FD[(Glayer.GL_FX[a * 4 + 0] + k) * 6 + 1];
                emon.Testport.assertThat(f >= next, "the fields are in stride order and do not overlap");
                covered += gtWidth(Glayer.GL_FD[(Glayer.GL_FX[a * 4 + 0] + k) * 6 + 2], Glayer.GL_FD[(Glayer.GL_FX[a * 4 + 0] + k) * 6 + 5]);
                next = f + gtWidth(Glayer.GL_FD[(Glayer.GL_FX[a * 4 + 0] + k) * 6 + 2], Glayer.GL_FD[(Glayer.GL_FX[a * 4 + 0] + k) * 6 + 5]);
                k += 1;
            }
            emon.Testport.assertEq(covered + Glayer.GL_FX[a * 4 + 3], Glayer.GL_FX[a * 4 + 2], "printed plus spare is the stride");
            a += 1;
        }
        emon.Testport.assertEq(a, 4, "four arenas");
    }
